        /* sdd-asis-lifecycle:begin tabDay_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnDateSearch('' + dlt_todaydisclosureList.getCellData(0, "calndDd") + '', '' + dma_loop.get("index") + '', true);return false;
        /* sdd-asis-lifecycle:end */

