/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    setTimeout(function() {
            AKCDiv.setStyle("display", "none");
        }, 200);
    if (!$c.date.isDate($c.util.getComponent('cal_selDate').getValue())) {
        await $c.win.alert("일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent("dma_fnSearch1Req").set("searchCodeType", "");
    }
    const selectedDate = $c.util.getComponent('cal_selDate').getValue();
    let tabDayIdx = -1;
    let tabDayVal = "";
    $("#searchForm").find("input[id=tabDayVal]").each(function(index) {
            if ($(this).val() === selectedDate) {
                tabDayIdx = index;
                tabDayVal = $(this).val();
            }
    });
    if (tabDayIdx < 0) {
        $("#searchForm").find("a[id=tabDay]").each(function() {
                if ($(this).hasClass("active")) {
                    $(this).removeClass("active");
                }
        });
        const vHtml = selectedDate.substr(5, 2) + "." + selectedDate.substr(8) + " (" + scwin.fnGetWeekday(selectedDate) + ")";
        const objSpan = $("#otherTabDay").find("span");
        objSpan.html(vHtml);
        if (!objSpan.hasClass("active")) {
            objSpan.addClass("active");
        }
        objSpan.click(async function() {
                await scwin.fnDateSearch(selectedDate, -1, true);
        });
        scwin.otherTabDay.setStyle("display", "");
    } else {
        await scwin.fnDateSearch(tabDayVal, tabDayIdx, false);
    }
    $c.util.getComponent("dma_fnSearch1Req").set("todayFlag", "N");
    $("#searchForm").find("a[id=tabDay]").each(function(index) {
            if (index == 0) {
                if ($(this).hasClass("active")) {
                    $c.util.getComponent("dma_fnSearch1Req").set("todayFlag", "Y");
                }
            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnSearch1Req").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnSearch1Req").set("method", "searchTodayDisclosureSub");
    $c.util.getComponent("dma_fnSearch1Req").set("forward", "todaydisclosure_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


