            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $c.util.getComponent("dma_fnSearch1Req").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnSearch1Req").set("pageIndex", "1");
    $c.util.getComponent("dma_fnSearch1Req").set("method", "searchTodayDisclosureSub");
    $c.util.getComponent("dma_fnSearch1Req").set("forward", "todaydisclosure_down");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTabClick
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx kosdaqSegment
 * @returns
 * @hidden N
*/
scwin.fnTabClick = async function (idx, kosdaqSegment) {
    /* sdd-asis-lifecycle:begin fnTabClick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(document).find("li[id=marketType]").each(function(i) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (i === idx) {
                $(this).addClass("active");
            }
    });
    let marketType = idx;
    if (idx === "3") {
        marketType = "6";
    } else {
        if (idx === "4") {
            marketType = "3";
        } else {
            if (idx === "0") {
                marketType = "";
            }
        }
    }
    $c.util.getComponent("dma_fnSearch1Req").set("marketType", marketType);
    if (kosdaqSegment) {
        $c.util.getComponent("dma_fnSearch1Req").set("kosdaqSegment", kosdaqSegment);
    } else {
        $c.util.getComponent("dma_fnSearch1Req").set("kosdaqSegment", "");
    }
    await scwin.fnInit();
    /* sdd-asis-lifecycle:end */
};


