/**
 * @method
 * @name scwin.fnGetWeekday
 * @author Inswave
 * @date 2026. 09. 29
 * @param sDate
 * @returns
 * @hidden N
*/
scwin.fnGetWeekday = function (sDate) {
    /* sdd-asis-lifecycle:begin fnGetWeekday — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const yy = parseInt(sDate.substr(0, 4), 10);
    const mm = parseInt(sDate.substr(5, 2), 10);
    const dd = parseInt(sDate.substr(8), 10);
    const d = new Date(yy, mm - 1, dd);
    const weekday = new Array(7);
    weekday[0] = "일";
    weekday[1] = "월";
    weekday[2] = "화";
    weekday[3] = "수";
    weekday[4] = "목";
    weekday[5] = "금";
    weekday[6] = "토";
    return weekday[d.getDay()];
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnBookmark
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnBookmark = function () {
    /* sdd-asis-lifecycle:begin fnBookmark — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cookieName = "krxComp";
    const cookies = $c.util.getSessionStorage(cookieName);
    if (cookies != null) {
        (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).removeAll ? ($c.util.getComponent('txt_myBookmark')).removeAll() : (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).setValue ? ($c.util.getComponent('txt_myBookmark')).setValue('') : void 0));
        const items = cookies.split("/");
        let max = 0;
        for (i in items) {
            if (max == 10) {
                break;
            }
            const item = items[i].split(",");
            const repIsuSrtCd = item[1];
            const corpName = item[2];
            const isurcd = item[3];
            if (undefined !== corpName && undefined !== isurcd) {
                if (corpName.indexOf('%') <= -1) {
                    $("#txt_myBookmark").append("<a href='#' onclick=\"fnBookmarkSearch('" + repIsuSrtCd + "','" + corpName + "'); return false;\" title=\"" + corpName + " 검색\" >" + corpName + "</a> ");
                }
            }
            max++;
        }
    }
    /* sdd-asis-lifecycle:end */
};


async function fnBookmarkSearch(repIsuSrtCd, corpName) {
    /* sdd-asis-lifecycle:begin fnBookmarkSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('AKCKwd').setValue(corpName);
    $c.util.getComponent("dma_fnSearch1Req").set("repIsuSrtCd", repIsuSrtCd);
    await scwin.fnInit();
    /* sdd-asis-lifecycle:end */
}
